function carInput(group,car,key,value,type='number'){if(state()?.view!=='parameters')click('workflow-step',{view:'parameters'});click('group',{index:String(group)});events.change({target:{dataset:{carGroup:String(group),carIndex:String(car),carKey:key},value:String(value),type,checked:!!value,matches:()=>false}});}
test('interface: prévia reflete velocidade editada por elevador e descarta gráfico inválido',()=>{
 click('load-example');carInput(1,0,'speed',.5);carInput(1,1,'speed',2.5);
 click('workflow-step',{view:'performance'});click('analysis-tab',{tab:'travel'});
 assert.match(app.innerHTML,/Prévia do grupo em edição/);
 assert.match(app.innerHTML,/elevador 1/);assert.match(app.innerHTML,/elevador 2/);
 assert.match(app.innerHTML,/Velocidade nominal 0,50 m\/s/);
 assert.match(app.innerHTML,/Velocidade nominal 2,50 m\/s/);
 assert.equal((app.innerHTML.match(/class="travel-line"/g)||[]).length,6);
 events.input({target:{dataset:{carGroup:'1',carIndex:'0',carKey:'speed'},value:'1.33',type:'number',matches:()=>false}});
 const preview=document.querySelector('#travel-preview');
 assert.match(preview.innerHTML,/Velocidade nominal 1,33 m\/s/);
 assert.doesNotMatch(preview.innerHTML,/Velocidade nominal 0,50 m\/s/);
 assert.equal(state().calculationComplete,false);
 assert.equal(document.querySelector('#print-report').innerHTML,'');
 events.input({target:{dataset:{carGroup:'1',carIndex:'0',carKey:'speed'},value:'',type:'number',matches:()=>false}});
 assert.equal((preview.innerHTML.match(/class="travel-line"/g)||[]).length,3);
 assert.match(preview.innerHTML,/population-warning/);
 assert.doesNotMatch(preview.innerHTML,/Velocidade nominal 1,33 m\/s|NaN|Infinity/);
 carInput(1,0,'speed',1.33);click('calculate');
 assert.equal(state().calculationComplete,true);
 assert.match(document.querySelector('#print-report').innerHTML,/Velocidade nominal 1,33 m\/s/);
 assert.match(document.querySelector('#print-report').innerHTML,/Velocidade nominal 2,50 m\/s/);
 click('load-example');
});
