test('interface v8.5: confirmação controla abas e dados são preservados ao desligar',()=>{click('load-example');click('workflow-step',{view:'parameters'});assert.match(app.innerHTML,/O prédio terá escadas/);assert.doesNotMatch(app.innerHTML,/data-tab="escalators"/);transportChoice('escalators','yes');assert.doesNotMatch(app.innerHTML,/data-tab="escalators"/);assert.equal(state().parameterTab,'traffic');events.change({target:{dataset:{buildingEscalator:'1'},checked:true,matches:()=>false}});assert.equal(state().draft.populationCalc.escalators.links.length,1);const bankId=state().draft.populationCalc.escalators.links[0].banks[0].id;transportChoice('escalators','no');assert.doesNotMatch(app.innerHTML,/data-tab="escalators"/);assert.equal(state().draft.populationCalc.escalators.enabled,false);assert.equal(state().draft.populationCalc.escalators.links[0].banks[0].id,bankId);transportChoice('escalators','yes');assert.equal(state().draft.populationCalc.escalators.links[0].banks[0].id,bankId);transportChoice('walkways','yes');assert.equal(state().parameterTab,'escalators');assert.doesNotMatch(app.innerHTML,/data-tab="walkways"/);click('add-walkway');assert.match(app.innerHTML,/id="walkway-0-length"/);events.input({target:{dataset:{walkwayIndex:'0',walkwayKey:'length'},value:'25',type:'number',matches:()=>false}});assert.equal(state().draft.transportEquipment.walkwaysRows[0].length,25);click('workflow-step',{view:'population'});assert.doesNotMatch(app.innerHTML,/id="escalator-title"|Configuração das esteiras rolantes/);});
test('interface v8.5: editar elevador individual altera cadastro e matriz por coluna',()=>{click('load-example');click('workflow-step',{view:'parameters'});input('groups.0.count',2);click('group',{index:'0'});assert.match(app.innerHTML,/id="car-0-1-capacity"/);const change=(j,key,value)=>events.change({target:{dataset:{carGroup:'0',carIndex:String(j),carKey:key},value:String(value),type:key==='door'?'select-one':'number',matches:()=>false}});change(0,'speed',2);change(1,'capacity',9);assert.equal(state().draft.groups[0].cars[0].speed,2);assert.equal(state().draft.groups[0].cars[1].capacity,9);assert.equal(document.querySelector('#print-report').innerHTML,'');click('calculate');assert.doesNotMatch(app.innerHTML,/class="errors"/);assert.match(document.querySelector('#print-report').innerHTML,/elevador 1|elevador 2/);assert.match(document.querySelector('#print-report').innerHTML,/<td>9<\/td>/);click('workflow-step',{view:'parameters'});const floor=state().draft.floorTable.rows[4];events.change({target:{dataset:{carGroup:'0',carIndex:'1',carKey:'servedFloorId',carFloor:floor.id},checked:false,type:'checkbox',matches:()=>false}});assert.equal(state().draft.groups[0].cars[1].servedFloorIds.includes(floor.id),false);assert.equal(state().draft.groups[0].cars[0].servedFloorIds.includes(floor.id),true);});
test('interface v8.5: pendência abre grupo correto e foca diretamente o campo',()=>{click('load-example');input('groups.1.speed','');click('workflow-step',{view:'traffic'});assert.match(app.innerHTML,/data-action="focus-pending"/);const matches=[...app.innerHTML.matchAll(/data-section="(\d+)" data-item="(\d+)"[^>]*>Velocidade \(m\/s\)/g)];assert.ok(matches.length);click('focus-pending',{section:matches[0][1],item:matches[0][2]});assert.equal(state().view,'parameters');assert.equal(state().group,1);assert.equal(document.querySelector('#car-1-0-speed').focused,true);assert.ok(app.innerHTML.indexOf('id="calculation-readiness"')>app.innerHTML.indexOf('id="manufacturer-mirror"'));});
test('interface v8.5.1: selecionar 3 inclui acesso e intermediários; remoção manual é preservada e sinalizada',()=>{click('load-example');click('workflow-step',{view:'parameters'});transportChoice('escalators','yes');events.change({target:{dataset:{buildingEscalator:'3'},checked:true,matches:()=>false}});assert.deepEqual(state().draft.floorTable.rows.slice(0,5).map(r=>r.escalatorServed),[true,true,true,true,false]);const main=app.innerHTML.match(/<input[^>]*data-building-escalator="0"[^>]*>/)[0];assert.doesNotMatch(main,/disabled/);assert.match(main,/checked/);events.change({target:{dataset:{buildingEscalator:'1'},checked:false,matches:()=>false}});assert.equal(state().draft.floorTable.rows[3].escalatorServed,true);assert.equal(state().draft.floorTable.rows[1].escalatorServed,false);assert.match(app.innerHTML,/Atenção: falta atendimento por escadas nos andares 1/);events.change({target:{dataset:{buildingEscalator:'0'},checked:false,matches:()=>false}});assert.equal(state().draft.floorTable.rows[0].escalatorServed,false);assert.match(app.innerHTML,/andares 0, 1/);events.change({target:{dataset:{buildingEscalator:'3'},checked:true,matches:()=>false}});assert.deepEqual(state().draft.floorTable.rows.slice(0,4).map(r=>r.escalatorServed),[true,true,true,true]);assert.equal(state().draft.populationCalc.escalators.capacityConfirmed,false);assert.equal(document.querySelector('#print-report').innerHTML,'');});

test('interface v8.6: renomear grupo preserva nome nos cálculos, relatório e cópia',()=>{click('load-example');input('groups.0.label','Elevadores sociais','text');carInput(0,0,'capacity',10);click('calculate');assert.match(app.innerHTML,/Estudo separado de cada grupo/);assert.match(app.innerHTML,/Elevadores sociais/);assert.match(document.querySelector('#print-report').innerHTML,/Elevadores sociais/);click('workflow-step',{view:'parameters'});click('copy-group');copyDestination('new');click('confirm-copy-group');assert.equal(state().draft.groups[0].label,'Elevadores sociais');assert.equal(state().calculationComplete,false);});

test('interface v8.7: parâmetros consultam a tabela por elevador, invalidam relatório e preservam medidas existentes',()=>{click('load-example');click('workflow-step',{view:'parameters'});click('parameter-tab',{tab:'dimensions'});assert.match(app.innerHTML,/Referência provisória de última altura e poço/);input('groups.0.dimensionReference.machineRoom','mrl','select-one');input('groups.0.dimensionReference.fabrication','standard','select-one');input('groups.0.dimensionReference.cabinHeight',2300);input('groups.0.dimensionReference.doorHeight',2100);assert.match(document.querySelector('#dimension-reference-group-0').innerHTML,/3.960,00 mm/);assert.match(document.querySelector('#dimension-reference-group-0').innerHTML,/1.100,00 mm/);assert.equal(state().draft.groups[0].siteDimensions.headroom,null);click('calculate');assert.match(document.querySelector('#print-report').innerHTML,/35 duplicados removidos/);assert.match(document.querySelector('#print-report').innerHTML,/referência provisória/);input('groups.0.dimensionReference.cabinHeight',2500);assert.equal(document.querySelector('#print-report').innerHTML,'');assert.equal(state().calculationComplete,false);assert.match(document.querySelector('#dimension-reference-group-0').innerHTML,/4.160,00 mm/);});

test('interface v8.8: matriz libera escadas, controles não pedem documento/confirmação e desmarcar todos oculta aba',()=>{click('load-example');click('workflow-step',{view:'parameters'});transportChoice('escalators','yes');assert.doesNotMatch(app.innerHTML,/data-tab="escalators"/);checkboxChange('populationCalc.escalators.enabled',true);assert.equal(state().draft.populationCalc.escalators.enabled,false);assert.match(toast.textContent,/Selecione ao menos um flag/);events.change({target:{dataset:{buildingEscalator:'1'},checked:true,matches:()=>false}});assert.match(app.innerHTML,/data-tab="escalators"/);click('parameter-tab',{tab:'escalators'});assert.match(app.innerHTML,/Controlar atendimento por escadas e esteiras rolantes/);assert.doesNotMatch(app.innerHTML,/data-path="[^\"]*(?:capacitySource|pairConfirmed|geometryConfirmed|capacityConfirmed)"/);input('populationCalc.escalators.links.0.banks.0.countUp',1);input('populationCalc.escalators.links.0.banks.0.countDown',1);input('populationCalc.escalators.links.0.banks.0.served',true,'checkbox');click('calculate');assert.equal(state().draft.population,0);events.change({target:{dataset:{buildingEscalator:'1'},checked:false,matches:()=>false}});events.change({target:{dataset:{buildingEscalator:'0'},checked:false,matches:()=>false}});click('workflow-step',{view:'parameters'});assert.doesNotMatch(app.innerHTML,/data-tab="escalators"/);assert.equal(state().draft.populationCalc.escalators.enabled,false);click('calculate');assert.equal(state().draft.population,396);});
test('interface v8.8: referência de caixa/cabina usa tabela e mantém escolha de variante por elevador',()=>{click('load-example');click('workflow-step',{view:'parameters'});click('parameter-tab',{tab:'dimensions'});input('groups.0.dimensionReference.machineRoom','mrl','select-one');assert.match(document.querySelector('#dimension-reference-group-0').innerHTML,/Frente mínima da caixa/);assert.match(document.querySelector('#dimension-reference-group-0').innerHTML,/1.500,00 mm/);assert.match(document.querySelector('#dimension-reference-group-0').innerHTML,/data-car-key="shaftRowId"/);const id=document.querySelector('#dimension-reference-group-0').innerHTML.match(/option value="(box-[a-z0-9]+)"/)[1];carInput(0,0,'shaftRowId',id);assert.equal(state().draft.groups[0].cars[0].shaftRowId,id);click('calculate');assert.match(document.querySelector('#print-report').innerHTML,/660 configurações/);assert.match(document.querySelector('#print-report').innerHTML,/1.500,00 mm/);});

test('interface v8.9: uma confirmação e uma aba, tipo por conjunto e mesma relação na esteira local',()=>{click('load-example');click('workflow-step',{view:'parameters'});assert.equal((app.innerHTML.match(/data-transport-kind=/g)||[]).length,1);assert.match(app.innerHTML,/id="transport-rolling"/);transportChoice('rolling','yes');assert.equal(state().draft.transportEquipment.rolling,true);assert.equal(state().draft.transportEquipment.escalators,true);assert.equal(state().draft.transportEquipment.walkways,true);events.change({target:{dataset:{buildingEscalator:'1'},checked:true,matches:()=>false}});click('parameter-tab',{tab:'escalators'});assert.match(app.innerHTML,/Escadas e esteiras rolantes/);assert.doesNotMatch(app.innerHTML,/data-tab="walkways"/);input('populationCalc.escalators.links.0.banks.0.kind','walkway','text');assert.equal(state().draft.populationCalc.escalators.links[0].banks[0].kind,'walkway');click('add-walkway');for(const [key,value] of Object.entries({label:'Passarela do hall',length:24,speed:.5,width:1000,count:2,capacity:4800,population:1200})){events.change({target:{dataset:{walkwayIndex:'0',walkwayKey:key},value:String(value),type:key==='label'?'text':'number',matches:()=>false}});}input('populationCalc.escalators.periodMinutes',5);input('populationCalc.escalators.utilizationPercent',80);input('populationCalc.escalators.demandPercent',50);assert.match(document.querySelector('#walkway-result-0').textContent,/640 pessoas na janela.*atende/);click('calculate');assert.ok(state().draft.transportEquipment.walkwaysRows[0].population===1200);assert.match(document.querySelector('#print-report').innerHTML,/Passarela do hall/);input('populationCalc.escalators.periodMinutes',3);assert.equal(document.querySelector('#print-report').innerHTML,'');assert.match(document.querySelector('#walkway-result-0').textContent,/384 pessoas na janela.*capacidade insuficiente/);const before=structuredClone(state().draft.transportEquipment.walkwaysRows);transportChoice('rolling','no');assert.equal(state().draft.populationCalc.escalators.enabled,false);assert.deepEqual(state().draft.transportEquipment.walkwaysRows,before);transportChoice('rolling','yes');assert.deepEqual(state().draft.transportEquipment.walkwaysRows,before);assert.equal(state().draft.populationCalc.escalators.links[0].banks[0].kind,'walkway');});

test('interface 9.1: copiar unidade ou tempos usa flags de destino e invalida relatórios',()=>{click('load-example');carInput(1,0,'open',3.21);carInput(1,1,'capacity',12);click('copy-car',{group:'1',car:'0',scope:'timing'});assert.match(app.innerHTML,/data-car-copy-target="0" disabled/);events.change({target:{dataset:{carCopyTarget:'1'},checked:true,disabled:false}});click('confirm-copy-car');assert.equal(state().draft.groups[1].cars[1].open,3.21);assert.equal(state().draft.groups[1].cars[1].capacity,12);assert.equal(state().calculationComplete,false);click('copy-car',{group:'1',car:'0',scope:'all'});events.change({target:{dataset:{carCopyTarget:'1'},checked:true,disabled:false}});click('confirm-copy-car');assert.equal(state().draft.groups[1].cars[1].capacity,8);click('autofill-car',{group:'1',car:'0'});assert.match(state().draft.groups[1].cars[0].timingSource,/Sugestão de projeto/);carInput(1,0,'close',5.99);assert.ok(document.querySelector('#car-1-0-close').classes.has('motion-warning-red'));assert.ok(document.querySelector('#car-1-0-open').classes.has('motion-warning-red'));});
test('interface 9.1: aplicação somente por grupo preserva composições e altera demanda',()=>{click('load-example');click('workflow-step',{view:'parameters'});assert.doesNotMatch(app.innerHTML,/data-path="use"|id="f-method"/);const before=state().draft.populationCalc.rows[0].amount;input('groups.1.use','single','select-one');assert.equal(state().draft.groups[0].use,'offices');assert.equal(state().draft.groups[1].use,'single');assert.equal(state().draft.populationCalc.rows[0].amount,before);click('calculate');assert.doesNotMatch(app.innerHTML,/class="errors"/);assert.match(document.querySelector('#print-report').innerHTML,/15,00%/);});
test('SilSec: fabricante pendente preserva relatório normativo e não inventa curvas FAB',()=>{click('load-example');input('groups.0.acceleration','');click('calculate');assert.equal(state().calculationComplete,true,document.querySelector('#toast').textContent);assert.match(document.querySelector('#print-report').innerHTML,/Somente os resultados NBR/);assert.doesNotMatch(document.querySelector('#print-report').innerHTML,/NaN|Infinity/);});


test('revisão: tempo de porta apagado mostra soma pendente e volta ao total ao preencher',()=>{
 click('load-example');carInput(0,0,'open','');carInput(0,0,'close',2.1);
 assert.equal(document.querySelector('#car-0-0-door-total').textContent,'— / 5,50 s');
 assert.equal(state().calculationComplete,false);
 carInput(0,0,'open',2.4);
 assert.equal(document.querySelector('#car-0-0-door-total').textContent,'4,50 / 5,50 s');
 click('load-example');
});

test('revisão: cópia da unidade sincroniza abertura dimensional vinculada ao destino',()=>{
 click('load-example');carInput(1,0,'width',900);carInput(1,1,'width',1100);
 input('groups.1.siteDimensions.carId',state().draft.groups[1].cars[1].id,'select-one');
 assert.equal(state().draft.groups[1].siteDimensions.doorWidth,1100);
 click('copy-car',{group:'1',car:'0',scope:'all'});
 events.change({target:{dataset:{carCopyTarget:'1'},checked:true,disabled:false}});
 click('confirm-copy-car');
 assert.equal(state().draft.groups[1].cars[1].width,900);
 assert.equal(state().draft.groups[1].siteDimensions.doorWidth,900);
 assert.equal(state().calculationComplete,false);
 click('load-example');
});
